  projectVersionError: {"zh-CN": "工程格式应为 pudding.pocket-studio，版本应为 1。", "zh-TW": "工程格式應為 pudding.pocket-studio，版本應為 1。", "en": "Project format must be pudding.pocket-studio, version 1."},
